=== check getDesktopLayoutCounts.ts for magic numbers ===
export type DesktopLayoutCounts = {
  stackedCount: number;
  gridCount: number;
  remainingCount: number;
  showButton: boolean;
};

/**
 * Desktop item-count layout, per SFCC-731's Acceptance Criteria (confirmed 2026-09-04): 3 items
 * -> 3 stacked, no grid; 4 -> 2 stacked + 2-up grid; 5 -> 2 stacked + 2-up grid + "+1"; 6 -> 2
 * stacked + 4-up grid; 7+ -> 2 stacked + 4-up grid + "+X" (X = total - 6). The grid only ever
 * shows 2 or 4 items (never an uneven 3) — at 5 total, one of the 3 items left after stacking is
 * held back behind "+1" rather than shown as a lopsided 3-cell row.
 *
 * Below 3, this generalises the same "everything stacked, no grid" shape; the AC doesn't cover
 * 1-2 items explicitly, so the single-image case keeps this component's existing, tested
 * behaviour (no button — nothing to view more of), and 2 extends the button-shown pattern
 * confirmed at 3.
 */
export const getDesktopLayoutCounts = (total: number): DesktopLayoutCounts => {
  if (total <= 3) {
    return { stackedCount: total, gridCount: 0, remainingCount: 0, showButton: total >= 2 };
  }
  const available = total - 2;
  if (available <= 2) return { stackedCount: 2, gridCount: available, remainingCount: 0, showButton: true };
  if (available === 3) return { stackedCount: 2, gridCount: 2, remainingCount: 1, showButton: true };
  return { stackedCount: 2, gridCount: 4, remainingCount: available - 4, showButton: true };
};
